package it.frociart.app;

import java.util.*;
import static it.frociart.app.FlowModel.*;

/** Emits Visual Basic .NET methods and structured control flow. No diagram interpreter is exported. */
final class FlowVisualBasic {
    static String templateNumber(double value){return number(value);}
    private FlowVisualBasic(){}
    static FlowSourceText generate(FlowSource.Program program,String runtime){return generate(program,runtime,"Programma");}
    static FlowSourceText generate(FlowSource.Program program,String runtime,String className){
        if(runtime==null||runtime.trim().isEmpty())throw new IllegalArgumentException("Il supporto Visual Basic .NET è vuoto.");
        if(className==null||!className.matches("[A-Za-z_][A-Za-z_0-9]*")||KEYWORDS.contains(className)||className.toLowerCase(Locale.ROOT).startsWith("_fc")||RESERVED_CLASSES.contains(className))throw new IllegalArgumentException("Nome della classe Visual Basic .NET non valido.");
        return new Writer(program).generate(runtime,className);
    }
    static String literal(String text){
        if(text==null)return "Nothing";List<String> pieces=new ArrayList<>();StringBuilder part=new StringBuilder();
        for(int i=0;i<text.length();i++){char c=text.charAt(i);if(!Character.isISOControl(c)&&c!=0x2028&&c!=0x2029&&c!=0x201C&&c!=0x201D&&c!=0xFF02&&!Character.isSurrogate(c)){part.append(c);continue;}if(Character.isHighSurrogate(c)&&i+1<text.length()&&Character.isLowSurrogate(text.charAt(i+1))){part.append(c).append(text.charAt(++i));continue;}if(part.length()>0){pieces.add("\""+part.toString().replace("\"","\"\"")+"\"");part.setLength(0);}pieces.add(String.format(Locale.ROOT,"Global.Microsoft.VisualBasic.Strings.ChrW(&H%04X)",(int)c));}
        if(part.length()>0)pieces.add("\""+part.toString().replace("\"","\"\"")+"\"");if(pieces.isEmpty())return "\"\"";if(pieces.size()==1&&pieces.get(0).startsWith("\""))return pieces.get(0);
        List<String> values=new ArrayList<>();for(String v:pieces)values.add(v.startsWith("\"")?v:v+".ToString()");String result="String.Concat(New String(){"+String.join(", ",values)+"})";return result.length()<=8192?result:encodedLiteral(text);
    }
    private static String encodedLiteral(String text){byte[] bytes=new byte[text.length()*2];for(int i=0;i<text.length();i++){char c=text.charAt(i);bytes[i*2]=(byte)c;bytes[i*2+1]=(byte)(c>>8);}String data=java.util.Base64.getEncoder().encodeToString(bytes);return "(New Global.System.Func(Of Byte(), String)(Function(_fc_literalBytes) New String(Global.System.Linq.Enumerable.ToArray(Global.System.Linq.Enumerable.Select(Global.System.Linq.Enumerable.Range(0, _fc_literalBytes.Length \\ 2), Function(_fc_literalIndex) Global.System.Convert.ToChar(CInt(_fc_literalBytes(_fc_literalIndex * 2)) Or (CInt(_fc_literalBytes(_fc_literalIndex * 2 + 1)) << 8))))))).Invoke(Global.System.Convert.FromBase64String(\""+data+"\"))";
    }
    private static Set<String> ciSet(Collection<String> values){Set<String> result=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);result.addAll(values);return result;}
    private static String bool(boolean value){return value?"True":"False";}
    private static final Set<String> KEYWORDS=ciSet(Arrays.asList("addhandler addressof aggregate alias and andalso as ascending async auto await binary boolean by byref byte byval call case catch cbool cbyte cchar cdate cdbl cdec char cint class clng cobj compare const continue csbyte cshort csng cstr ctype cuint culng cushort custom date decimal declare default delegate descending dim directcast distinct do double each else elseif end endif enum equals erase error event exit explicit false finally for friend from function get gettype getxmlnamespace global gosub goto group handles if implements imports in inherits integer interface into is isfalse isnot istrue iterator join key let lib like long loop me mid mod module mustinherit mustoverride mybase myclass namespace narrowing new next not notinheritable notoverridable nothing object of off on operator option optional or order orelse overloads overridable overrides paramarray partial preserve private property protected public raiseevent readonly redim rem removehandler resume return sbyte select set shadows shared short single skip static step stop strict string structure sub synclock take text then throw to true try trycast typeof uinteger ulong unicode until ushort using variant wend when where while widening with withevents writeonly xor yield".split(" ")));
    private static final Set<String> RESERVED_CLASSES=ciSet(Arrays.asList("Value Values VectorValue ValueFormatter TypeSpec Intrinsics IntrinsicOperations FlowException FlowFileRequestKind FlowFileRequest FlowTextFiles FlowTurtle Variables ArrayCell ArrayArgument System Console BitConverter String Math Object Double Int32 Int64 Boolean Array List Dictionary HashSet Func Action File FileStream FileMode FileAccess FileShare Path Stream Encoding UTF8Encoding UnicodeEncoding StringBuilder CultureInfo NumberStyles BigInteger Regex Guid Exception IOException UnauthorizedAccessException ArgumentException Enumerable MidpointRounding ReadOnlyCollection Random".split(" ")));
    private static String identifier(String name){StringBuilder b=new StringBuilder();for(char c:name.toCharArray())if(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='_')b.append(c);else b.append(String.format(Locale.ROOT,"_u%04x",(int)c));String value=b.toString();if(value.isEmpty()||Character.isDigit(value.charAt(0)))value="value_"+value;if(value.toLowerCase(Locale.ROOT).startsWith("_fc")||KEYWORDS.contains(value))value="value_"+value;return value;}
    private static String unique(String seed,Set<String> names){String value=seed;int n=2;while(!names.add(value))value=seed+"_"+(n++);return value;}
    private static String number(double n){if(n==0)return "Value.number(0R)";if(Math.abs(n)<=9000000000d){long power=1;for(int digits=0;digits<=6;digits++,power*=10){double scaled=n*power;if(scaled!=Math.floor(scaled))continue;String text=Long.toString((long)Math.abs(scaled));while(text.length()<digits+1)text="0"+text;if(digits>0)text=text.substring(0,text.length()-digits)+"."+text.substring(text.length()-digits);if(n<0)text="-"+text;if(Double.parseDouble(text)==n)return "Value.number("+text+"R)";}}return String.format(Locale.ROOT,"Value.number(BitConverter.Int64BitsToDouble(&H%016XL))",Double.doubleToLongBits(n));}
    private static final class Symbol {final String name,original;Symbol(String name,String original){this.name=name;this.original=original;}}
    private static final class Helper {final String name;final FlowSource.Expression expression;final FlowSource.Block block;final Set<String> staged;final boolean track;Helper(String name,FlowSource.Expression e,FlowSource.Block b,Set<String> s,boolean t){this.name=name;expression=e;block=b;staged=new HashSet<>(s);track=t;}}
    private static final class Writer {
        final FlowSource.Program program;final FlowSourceText.Builder output;
        final Map<String,String> functions=new HashMap<>(),classes=new HashMap<>();
        final Set<String> globals=ciSet(Arrays.asList("Value","Values","VectorValue","ValueFormatter","TypeSpec","Intrinsics","IntrinsicOperations","FlowException","Double","System","Console","BitConverter","_fc","Programma","Main","run","ToString","GetHashCode","Equals","GetType","Finalize","MemberwiseClone","ReferenceEquals"));
        Map<String,Symbol> names;List<Symbol> symbols;Map<String,String> blockMethods;List<Helper> helpers;FlowSource.Scope scope;int temporary;final boolean references;
        Writer(FlowSource.Program p){program=p;boolean refs=false;for(FlowSource.Scope s:p.scopes)for(FlowSource.Parameter v:s.parameters)refs|=v.byReference;references=refs;output=new FlowSourceText.Builder(p,"vbnet");int i=0;for(FlowSource.Scope s:p.scopes){classes.put(s.id,"_fc_Scope"+(i++));if(s.id!=null)functions.put(s.id,unique("flow_"+identifier(s.name),globals));}}
        void addLine(String text,int indent,FlowSource.Block block){output.addLine(text,indent,block==null?new FlowSourceText.Origin[0]:new FlowSourceText.Origin[]{new FlowSourceText.Origin(scope.id,block.id)});}
        void line(String text,int indent,FlowSource.Block block){if(text.length()<=3000||text.trim().startsWith("'")){addLine(text,indent,block);return;}int start=0,split=-1;boolean quoted=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"'){if(quoted&&i+1<text.length()&&text.charAt(i+1)=='"'){i++;continue;}quoted=!quoted;}if(!quoted&&c==',')split=i+1;if(i-start>3000&&split>start){addLine(text.substring(start,split),indent+(start==0?0:1),block);start=split;split=-1;}}addLine(text.substring(start),indent+(start==0?0:1),block);}

        void line(String text,int indent){line(text,indent,null);}
        FlowSourceText generate(String runtime,String className){
            line("Option Strict On",0);line("Option Explicit On",0);line("Option Infer On",0);line("' Generato con Frociart — autore del software: mamt104",0);line("' Progetto: "+literal(program.title),0);line("' Visual Basic .NET. Salva come "+className+".vb; compila con vbc /r:System.Numerics.dll "+className+".vb.",0);
            for(String imp:new String[]{"Microsoft.VisualBasic","System","System.IO","System.Text","System.Linq","System.Collections.Generic","System.Collections.ObjectModel","System.Globalization","System.Numerics","System.Text.RegularExpressions"})line("Imports "+imp,0);
            line("",0);line("Public NotInheritable Class "+className,0);line("Private Shared _fc As New _fc_Runtime()",1);line("Public Shared Function Main(args As String()) As Integer",1);line("Console.InputEncoding = New UTF8Encoding(False)",2);line("Console.OutputEncoding = New UTF8Encoding(False)",2);line("Return If(_fc.[run](Function() (New _fc_Scope0()).run(), True), 0, 1)",2);line("End Function",1);
            for(FlowSource.Scope s:program.scopes){if(s.id!=null){List<String> ps=new ArrayList<>(),args=new ArrayList<>();Set<String> used=ciSet(globals);for(FlowSource.Parameter p:s.parameters){String name=unique(identifier(p.name),used);ps.add(name+" As Value");args.add(name);}line("Private Shared Function "+functions.get(s.id)+"("+String.join(", ",ps)+") As Value",1);line("Return (New "+classes.get(s.id)+"()).run("+String.join(", ",args)+")",2);line("End Function",1);}writeScope(s);}
            line("",1);line("' --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---",1);for(String text:runtime.replace("__FROCIART_PROGRAM__",className).replace("\r\n","\n").replace('\r','\n').split("\n",-1))line(text,1);line("End Class",0);return output.build();
        }
        void collect(FlowSource.Expression e,java.util.function.Consumer<String> add){if(e==null)return;if(e.kind==FlowSource.ExpressionKind.Variable)add.accept(e.text);for(FlowSource.Expression child:e.children)collect(child,add);}
        void writeScope(FlowSource.Scope s){
            scope=s;for(FlowSource.Block annotation:s.notes)line("' Annotazione: "+literal(annotation.text),1,annotation);for(FlowSource.Block note:s.blocks)if(note.comment!=null&&!note.comment.isEmpty())line("' Nota ("+(s.blocks.indexOf(note)+1)+"): "+literal(note.comment),1,note);temporary=0;names=new LinkedHashMap<>();symbols=new ArrayList<>();helpers=new ArrayList<>();blockMethods=new LinkedHashMap<>();Set<String> used=ciSet(globals);
            java.util.function.Consumer<String> add=name->{if(name!=null&&!names.containsKey(name.toLowerCase(Locale.ROOT))){Symbol sym=new Symbol(unique(identifier(name),used),name);names.put(name.toLowerCase(Locale.ROOT),sym);symbols.add(sym);}};for(FlowSource.Parameter p:s.parameters)add.accept(p.name);
            int index=0;for(FlowSource.Block b:s.blocks){blockMethods.put(b.id,"_fc_block"+(index++));FlowSource.Operation o=b.operation;if(o.input!=null){add.accept(o.input.name);collect(o.input.index,add);}if(o.declaration!=null){for(String n:o.declaration.names)add.accept(n);collect(o.declaration.size,add);}for(FlowSource.Write w:o.writes){add.accept(w.target.name);collect(w.value,add);collect(w.target.index,add);}collect(o.value,add);}
            line("",1);line("Private NotInheritable Class "+classes.get(s.id),1);for(Symbol sym:symbols){line("Private "+sym.name+" As Value",2);line("Private _fc_type_"+sym.name+" As TypeSpec",2);}
            List<String> args=new ArrayList<>(),pnames=new ArrayList<>(),pvalues=new ArrayList<>();index=0;for(FlowSource.Parameter p:s.parameters){String a="_fc_arg"+(index++);args.add(a+" As Value");pnames.add(literal(symbol(p.name).original));pvalues.add(a);}
            line("Friend Function run("+String.join(", ",args)+") As Value",2);line("_fc.[guardCall]()",3);index=0;for(FlowSource.Parameter p:s.parameters)line(symbol(p.name).name+" = _fc."+(p.byReference?"checkReference":"checkType")+"(_fc_arg"+(index++)+", "+p.type+(p.byReference?"":", "+bool(p.isArray))+")",3);
            line("_fc.[enter]("+literal(s.id==null?null:s.name)+", New String(){"+String.join(", ",pnames)+"}, New Value(){"+String.join(", ",pvalues)+"}"+(references?", True":"")+")",3);line("Try",3);line("_fc.[checkMemory]()",4);
            FlowSourcePlan plan=FlowSourcePlan.create(s);if(plan.structured)statements(plan.statements,4);else explicit(4);line("Catch ex As Exception",3);line("_fc.[captureError]()",4);line("Throw",4);line("Finally",3);line("_fc.[leave]()",4);line("End Try",3);line("End Function",2);
            for(FlowSource.Block b:s.blocks)instruction(b);for(int i=0;i<helpers.size();i++){Helper h=helpers.get(i);line("Private Function "+h.name+"() As Value",2,h.block);String e=expression(h.expression,h.block,h.staged,0,h.track);line("Return "+e,3,h.block);line("End Function",2,h.block);}line("End Class",1);
        }
        Symbol symbol(String name){return names.get(name.toLowerCase(Locale.ROOT));}
        String name(String name,Set<String> staged){Symbol sym=symbol(name);return references?"_fc.[lookup]("+literal(sym.original)+")":"_fc.[value]("+(staged.contains(name.toLowerCase(Locale.ROOT))?"_fc.[staged]("+literal(sym.original)+")":sym.name)+", "+literal(sym.original)+")";}
        FlowSource.Scope callee(String id){if(id!=null)for(FlowSource.Scope s:program.scopes)if(id.equals(s.id))return s;return null;}
        boolean calls(FlowSource.Expression e){if(e==null)return false;if(e.functionId!=null)return true;for(FlowSource.Expression c:e.children)if(calls(c))return true;return false;}
        String expression(FlowSource.Expression e,FlowSource.Block block,Set<String> staged,int depth,boolean track){
            if(e==null)return "Nothing";if(depth==0)track|=calls(e);if(depth>=24){String helper="_fc_expr"+(++temporary);helpers.add(new Helper(helper,e,block,staged,track));return helper+"()";}
            final boolean tracked=track;final int key=track?++temporary:0;
            java.util.function.Function<FlowSource.Expression,String> child=c->{String value=expression(c,block,staged,depth+1,tracked);return tracked?"_fc.[hold]("+key+", "+value+")":value;};
            java.util.function.Function<String,String> finish=value->tracked&&!e.children.isEmpty()?"_fc.[release]("+key+", "+value+")":value;
            switch(e.kind){
                case Number:return number(e.number);case Text:return "Value.text("+literal(e.text)+")";case Boolean:return "Value.logical("+bool(e.bool)+")";
                case Variable:return name(e.text,staged);
                case Vector:{List<String> values=new ArrayList<>();for(FlowSource.Expression c:e.children)values.add(child.apply(c));return finish.apply("Value.vector(New Value(){"+String.join(", ",values)+"})");}
                case Index:{String target=child.apply(e.children.get(0));return finish.apply(references&&e.children.get(0).kind==FlowSource.ExpressionKind.Variable?"_fc.[atName]("+literal(symbol(e.children.get(0).text).original)+", Function() "+child.apply(e.children.get(1))+")":"_fc.[at]("+target+", Function() "+child.apply(e.children.get(1))+")");}
                case Unary:return finish.apply("_fc.[unary]("+literal(e.text)+", "+child.apply(e.children.get(0))+")");
                case Call:{FlowSource.Scope called=callee(e.functionId);List<String> values=new ArrayList<>();for(int i=0;i<e.children.size();i++){FlowSource.Expression c=e.children.get(i);values.add(called!=null&&called.parameters.get(i).byReference?"_fc.[hold]("+key+", _fc.[reference]("+literal(symbol(c.text).original)+", "+declaration(c.text)+", "+parameter(c.text)+"))":child.apply(c));}String args=String.join(", ",values);return e.functionId==null?finish.apply("_fc.[intrinsic]("+literal(e.text)+(args.isEmpty()?"":", "+args)+")"):"_fc.[call]("+key+", Function() "+functions.get(e.functionId)+"("+args+"))";}
                case Binary:{String a=child.apply(e.children.get(0)),b=child.apply(e.children.get(1));if(e.text.equals("and")||e.text.equals("or"))return finish.apply("Value.logical("+a+".asBoolean() "+(e.text.equals("and")?"AndAlso":"OrElse")+" "+b+".asBoolean())");return finish.apply("_fc.[binary]("+literal(e.text)+", "+a+", "+b+")");}
                default:throw new IllegalArgumentException("Espressione Visual Basic .NET non supportata.");
            }
        }
        String expression(FlowSource.Expression e,FlowSource.Block block){return expression(e,block,Collections.emptySet(),0,false);}
        void statements(List<FlowSourcePlan.Statement> list,int indent){for(FlowSourcePlan.Statement s:list){if(s.kind==FlowSourcePlan.Kind.Instruction)line((s.block.kind==END?"Return ":"")+blockMethods.get(s.block.id)+"()",indent,s.block);else if(s.kind==FlowSourcePlan.Kind.Repeat){line("Do",indent,s.entryBlock());statements(s.body,indent+1);line("Loop While "+(s.loopOnTrue?"":"Not ")+blockMethods.get(s.block.id)+"().asBoolean()",indent,s.block);}else if(s.kind==FlowSourcePlan.Kind.While){line("While "+(s.loopOnTrue?"":"Not ")+blockMethods.get(s.block.id)+"().asBoolean()",indent,s.block);statements(s.body,indent+1);line("End While",indent,s.block);}else{line("If "+blockMethods.get(s.block.id)+"().asBoolean() Then",indent,s.block);statements(s.body,indent+1);line("Else",indent,s.block);statements(s.otherwise,indent+1);line("End If",indent,s.block);}}}
        void explicit(int indent){line("' Collegamenti espliciti per conservare questo grafo.",indent);line("Dim _fc_next As String = "+literal(scope.startId),indent);line("Do",indent);line("Select Case _fc_next",indent+1);for(FlowSource.Block b:scope.blocks){line("Case "+literal(b.id),indent+2,b);if(b.kind==DECISION)line("_fc_next = If("+blockMethods.get(b.id)+"().asBoolean(), "+literal(b.next("true"))+", "+literal(b.next("false"))+")",indent+3,b);else if(b.kind==END)line("Return "+blockMethods.get(b.id)+"()",indent+3,b);else{line(blockMethods.get(b.id)+"()",indent+3,b);line("_fc_next = "+literal(b.next("next")),indent+3,b);}}line("Case Else",indent+2);line("Throw problem(\"Collegamento non valido nel sorgente modificato.\")",indent+3);line("End Select",indent+1);line("Loop",indent);}
        String declaration(String n){return "_fc_type_"+symbol(n).name;}
        String parameter(String n){for(FlowSource.Parameter p:scope.parameters)if(p.name.equalsIgnoreCase(n))return "New TypeSpec("+p.type+", "+bool(p.isArray)+", 0)";return "Nothing";}
        String convert(String value,String n){return "_fc.[convert]("+value+", "+declaration(n)+", "+parameter(n)+")";}
        void instruction(FlowSource.Block b){FlowSource.Operation o=b.operation;String method=blockMethods.get(b.id);line("Private Function "+method+"() As Value",2,b);java.util.function.Consumer<String> emit=text->line(text,3,b);
            if(b.kind==DECISION){emit.accept("Return Value.logical(_fc.[test](Function() "+expression(o.value,b)+"))");line("End Function",2,b);return;}
            emit.accept(b.kind==INPUT?"_fc.[guard]()":"_fc.[step]()");if(b.kind==END){if(scope.id==null)emit.accept("_fc.[finishFiles]()");emit.accept(scope.id==null||scope.returnType==VOID?"Return Nothing":"Return _fc.[checkType]("+expression(o.value,b)+", "+scope.returnType+", "+bool(scope.returnIsArray)+")");line("End Function",2,b);return;}
            if(b.kind==PROCESS){emit.accept("_fc.[begin]()");Set<String> staged=new LinkedHashSet<>();List<FlowSource.Write> writes=o.writes;List<String> assignments=new ArrayList<>();for(int i=0;i<writes.size();i++){String part="_fc_assign"+(++temporary);assignments.add(part);emit.accept(part+"()");}emit.accept("_fc.[commit]()");for(FlowSource.Write w:writes)if(staged.add(w.target.name.toLowerCase(Locale.ROOT)))emit.accept(symbol(w.target.name).name+" = _fc.[variable]("+literal(symbol(w.target.name).original)+")");emit.accept("Return Nothing");line("End Function",2,b);staged.clear();
                for(int i=0;i<writes.size();i++){FlowSource.Write w=writes.get(i);line("Private Sub "+assignments.get(i)+"()",2,b);String value=expression(w.value,b,staged,0,false);if(w.target.index!=null)value=references?"_fc.[setAfterName]("+value+", "+literal(symbol(w.target.name).original)+", Function() "+expression(w.target.index,b,staged,0,false)+")":"_fc.[setAfter]("+value+", "+name(w.target.name,staged)+", Function() "+expression(w.target.index,b,staged,0,false)+")";line("_fc.[stage]("+literal(symbol(w.target.name).original)+", "+convert(value,w.target.name)+(references&&w.target.index!=null?", True, True":"")+")",3,b);line("End Sub",2,b);staged.add(w.target.name.toLowerCase(Locale.ROOT));}return;}
            if(b.kind==DECLARE){FlowSource.Declaration d=o.declaration;emit.accept("Dim _fc_size As Integer = Intrinsics.[integer]("+(d.isArray()?expression(d.size,b):"Value.number(0R)")+", 0, 1024, \"La dimensione\")");emit.accept("_fc.[begin]()");for(String n:d.names)emit.accept("_fc.[stage]("+literal(symbol(n).original)+", _fc.[initial]("+d.type+", "+bool(d.isArray())+", _fc_size), False)");emit.accept("_fc.[commit](True)");for(String n:d.names){emit.accept(symbol(n).name+" = _fc.[variable]("+literal(symbol(n).original)+")");emit.accept(declaration(n)+" = New TypeSpec("+d.type+", "+bool(d.isArray())+", _fc_size)");}}
            else if(b.kind==INPUT||b.kind==READ_FILE){FlowSource.Target t=o.input;String suffix=declaration(t.name)+", "+parameter(t.name)+", "+(t.index==null?"Nothing, Nothing":name(t.name,Collections.emptySet())+", Function() "+expression(t.index,b));emit.accept(symbol(t.name).name+" = _fc."+(b.kind==INPUT?"read(":"readFile(")+literal(symbol(t.name).original)+", "+(b.kind==INPUT?literal(b.prompt==null?"":b.prompt)+", ":"")+suffix+")");if(b.kind==INPUT)emit.accept("_fc.[step]()");}
            else if(b.kind!=START&&b.kind!=PAUSE){if(b.kind==OPEN_FILE)emit.accept("_fc.[requireClosed]("+bool(o.fileReading)+")");if(b.kind==WRITE_FILE)emit.accept("_fc.[requireWrite]()");String e=expression(o.value,b);switch(b.kind){case OUTPUT:emit.accept("_fc.[emit]("+e+(o.outputNewline?"":", False")+")");break;case CALL:emit.accept("Call "+e);break;case OPEN_FILE:emit.accept("_fc.[openFile]("+bool(o.fileReading)+", "+e+")");break;case WRITE_FILE:emit.accept("_fc.[writeFile]("+e+", "+bool(o.fileNewline)+")");break;case CLOSE_FILE:emit.accept("_fc.[closeFile]("+bool(o.fileReading)+")");break;case TURTLE_FORWARD:case TURTLE_TURN:case TURTLE_HOME:case TURTLE_CLEAR:case TURTLE_PEN:emit.accept("_fc.[turtle]("+b.kind+", "+e+", "+bool(b.kind==TURTLE_FORWARD?o.turtleDraw:o.turtleLeft)+")");break;default:throw new IllegalArgumentException("Blocco Visual Basic .NET non supportato.");}}
            emit.accept("Return Nothing");line("End Function",2,b);
        }

    }
}
